ps": [{"rel": "auto_related_family", "node": "FAM:SF-APPA-063"}]}, {"id": "FAM:SF-APPA-010", "label": "Study family SF-APPA-010: Adversarial best-response v1: equilibrium strategy vs actual", "score": 0.216, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPA-010 (0.17)", "request matches VAR:PPP_points_per_possession (0.25); FAM:SF-APPA-010 auto_measures VAR:PPP_points_per_possession"], "attributes": {"observed_research_question": "Adversarial best-response v1: equilibrium strategy vs actual", "auto_outcome_status": "inconclusive", "observed_hypothesis": "The system's offensive strategy survives optimal defensive adjustment and beats what teams ran.", "observed_result": "Eq vs actual +1.16 pts/100; beats actual 127/240 (53%); vs baseline eq +8.52 pts/100; converged 159/240.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "Doc verdict 'MARGINAL'; equilibrium PPP is model-implied not observed.", "observed_sample_and_power": "240 matchups", "auto_validation_status": "same_pipeline_validation; evidence: APPA-010: '240 matchups, 23,922 holdout possessions; iterative best-response to approximate nash eq'", "observed_method": "240 matchups, 23,922 holdout possessions; iterative best-response to approximate Nash equilibrium, model-scored PPP.", "observed_verdict": "inconclusive"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPA-011"}]}], "n_results": 4}

